import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)
    if n == 0:
        print(0)
        return
    # For each character, track positions
    char_positions = {}
    for i, ch in enumerate(s):
        if ch not in char_positions:
            char_positions[ch] = []
        char_positions[ch].append(i)

    min_k = n + 1  # Max possible k is n+1 (if all characters distinct, then max gap = n, k = n for each character? Actually if all distinct, then each character appears once, max gap for each is max(gap before first, after last) = max(len-1, len-1) = len-1? Let's think. String 'abcde', len=5. For 'a', first at 0, last at 0. gap before = 0, after = 4 (indices 1..4), max gap = 4. k = 4. For 'b', gap before = 1 (index 0), after = 3 (indices 3,4). max = 3. k = 3. So answer 3. Indeed example 3. So max gap = n-1 for a single occurrence.

    for ch, positions in char_positions.items():
        m = len(positions)
        if m == 1:
            # gap before first = positions[0]
            # gap after last = n - 1 - positions[0]
            gap = max(positions[0], n - 1 - positions[0])
        else:
            # gaps between consecutive
            max_gap = 0
            for i in range(m - 1):
                gap = positions[i+1] - positions[i] - 1
                if gap > max_gap:
                    max_gap = gap
            # Also check gap before first and after last
            gap = max(max_gap, positions[0], n - 1 - positions[-1])
        if gap < min_k:
            min_k = gap

    print(min_k)

if __name__ == '__main__':
    solve()
