import sys

def expand_ipv6(short):
    """Expand a shortened IPv6 address to its full form"""
    if '::' in short:
        # Split by ::
        parts = short.split('::')
        left = parts[0].split(':') if parts[0] else []
        right = parts[1].split(':') if parts[1] else []

        # Calculate how many zero blocks to insert
        num_zero_blocks = 8 - len(left) - len(right)

        # Expand each block
        expanded = []
        for block in left:
            expanded.append(block.zfill(4))

        for _ in range(num_zero_blocks):
            expanded.append('0000')

        for block in right:
            expanded.append(block.zfill(4))

        return ':'.join(expanded)
    else:
        # No ::, just expand each block
        blocks = short.split(':')
        expanded = [block.zfill(4) for block in blocks]
        return ':'.join(expanded)

n = int(sys.stdin.readline())
for _ in range(n):
    short = sys.stdin.readline().strip()
    full = expand_ipv6(short)
    print(full)
"}

