def is_perfect_cube(x):
    if x < 1:
        return False

    # Estimate cube root using binary search
    low = 1
    high = x

    while low <= high:
        mid = (low + high) // 2
        cube = mid * mid * mid

        if cube == x:
            return True
        elif cube < x:
            low = mid + 1
        else:
            high = mid - 1

    return False

