def is_valid(a, b):

    def check(e, f):
        # Check if we can reach (e, f) from (0, 0)
        # with moves (2, 1) and (1, 2)

        # Conditions: 2e - f divisible by 3, e - f divisible by 3, non-negative
        cond1 = (2 * e - f) % 3 == 0
        cond2 = (e - f) % 3 == 0
        cond3 = 2 * e - f >= 0
        cond4 = e - f >= 0

        return cond1 and cond2 and cond3 and cond4

    # Find prime factorization of a and b
    factors = {}

    # Get prime factors of a
    temp = a
    i = 2
    while i * i <= temp:
        while temp % i == 0:
            if i not in factors:
                factors[i] = [0, 0]  # (a, b) exponents
            factors[i][0] += 1
            temp //= i
    if temp > 1:
        if temp not in factors:
            factors[temp] = [0, 0]
        factors[temp][0] += 1

    # Get prime factors of b
    temp = b
    i = 2
    while i * i <= temp:
        while temp % i == 0:
            if i not in factors:
                factors[i] = [0, 0]
            factors[i][1] += 1
            temp //= i
    if temp > 1:
        if temp not in factors:
            factors[temp] = [0, 0]
        factors[temp][1] += 1

    # Check all prime factors
    for prime in factors:
        e, f = factors[prime]
        if not check(e, f):
            return False

    return True

n = int(input())
for _ in range(n):
    a, b = map(int, input().split())
    if is_valid(a, b):
        print("Yes")
    else:
        print("No")
