import sys

def count_digits(s):
    """Count the frequency of each digit in string s."""
    freq = {}
    for ch in s:
        if ch.isdigit():
            freq[ch] = freq.get(ch, 0) + 1
    return freq

def solve():
    # Read input
    t = sys.stdin.readline().strip()
    pieces = sys.stdin.readline().strip()

    # Count digits in target number t
    target_count = {}
    for ch in t:
        if ch.isdigit():
            target_count[ch] = target_count.get(ch, 0) + 1

    # Count digits in pieces
    piece_count = count_digits(pieces)

    # Calculate available pieces for each digit
    # Interchangeable pairs: 6/9 and 2/5
    interchangeable = {
        '6': ['6', '9'],
        '9': ['6', '9'],
        '2': ['2', '5'],
        '5': ['2', '5']
    }

    # For each digit in target, calculate max possible instances
    max_instances = float('inf')
    for target_digit in target_count:
        # Count total available pieces for this digit
        available = piece_count.get(target_digit, 0)

        # Check if there's an interchangeable pair
        if target_digit in interchangeable:
            for alt_digit in interchangeable[target_digit]:
                available += piece_count.get(alt_digit, 0)

        # Number of this digit needed in t
        needed = target_count[target_digit]

        # Max instances for this digit
        max_instances = min(max_instances, available // needed)

    print(max_instances)

if __name__ == "__main__":
    solve()
