MOD = 10**9 + 7

N, L, M = map(int, input().split())
costs_in = list(map(int, input().split()))
costs_between = list(map(int, input().split()))
costs_out = list(map(int, input().split()))

# Initialize with entry costs
prev_dp = [0] * M
for cost in costs_in:
    prev_dp[cost % M] = (prev_dp[cost % M] + 1) % MOD

# Matrix for transitioning between layers
# transition[i][j] = number of ways to go from remainder i to remainder j in one layer
transition = [[0] * M for _ in range(M)]
for j in range(N):
    cost_j = costs_between[j]
    for i in range(M):
        # From remainder i, after traveling to city j, new remainder is (i + cost_j) % M
        new_remainder = (i + cost_j) % M
        transition[i][new_remainder] += 1

# Compute transition^(L-1) using fast exponentiation
matrix = transition
times = L - 1
for _ in range(times):
    matrix = matrix_mult(matrix, transition)

# Apply to initial DP
final_dp = [0] * M
for i in range(M):
    if prev_dp[i] == 0:
        continue
    # After L-1 layers, transition from remainder i
    for j in range(M):
        final_dp[j] = (final_dp[j] + prev_dp[i] * matrix[i][j]) % MOD

# Add exit costs
final_answer = [0] * M
for j in range(N):
    cost_j = costs_out[j]
    for remainder, count in enumerate(final_dp):
        if count == 0:
            continue
        new_remainder = (remainder + cost_j) % M
        final_answer[new_remainder] = (final_answer[new_remainder] + count) % MOD

print(final_answer[0])

# Matrix multiplication
def matrix_mult(a, b):
    result = [[0] * M for _ in range(M)]
    for i in range(M):
        for k in range(M):
            if a[i][k] == 0:
                continue
            for j in range(M):
                result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % MOD
    return result
