def is_good(s):
    # A string is good if we can perform operations until only one character remains
    # We can try eliminating from left to right or right to left

    # Try eliminating from left to right
    s_left = s[:]
    i = 0
    while i < len(s_left):
        if s_left[i] == '>':
            if i + 1 < len(s_left) and s_left[i+1] == '<':
                # Choose '>' to delete the '<' after it
                s_left.pop(i+1)
                i = 0  # Reset because the string has changed
            else:
                i += 1
        elif s_left[i] == '<':
            if i > 0 and s_left[i-1] == '>':
                # Choose '<' to delete the '>' before it
                s_left.pop(i-1)
                i = 0  # Reset because the string has changed
            else:
                i += 1

    # Try eliminating from right to left
    s_right = s[:]
    i = len(s_right) - 1
    while i >= 0:
        if s_right[i] == '>':
            if i + 1 < len(s_right) and s_right[i+1] == '<':
                # Choose '>' to delete the '<' after it
                s_right.pop(i+1)
                i = len(s_right) - 1  # Reset because the string has changed
            else:
                i -= 1
        elif s_right[i] == '<':
            if i > 0 and s_right[i-1] == '>':
                # Choose '<' to delete the '>' before it
                s_right.pop(i-1)
                i = len(s_right) - 1  # Reset because the string has changed
            else:
                i -= 1

    return len(s_left) == 1 or len(s_right) == 1

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input().strip()

        # Try all possible deletions (brute force for small n)
        min_deletions = n  # Worst case

        # We can delete any subset of characters
        for mask in range(1 << n):
