class SegmentTreeNode:
    def __init__(self, l, r, k):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.min = [float('inf')] * k  # min in each dimension
        self.max = [-float('inf')] * k  # max in each dimension

class SegmentTree:
    def __init__(self, data, k):
        self.n = len(data)
        self.k = k
        self.root = self.build(data, 0, self.n - 1)

    def build(self, data, l, r):
        node = SegmentTreeNode(l, r, self.k)
        if l == r:
            # Leaf node
            for i in range(self.k):
                node.min[i] = data[l][i]
                node.max[i] = data[l][i]
        else:
            mid = (l + r) // 2
            node.left = self.build(data, l, mid)
            node.right = self.build(data, mid + 1, r)
            # Merge results
            for i in range(self.k):
                node.min[i] = min(node.left.min[i], node.right.min[i])
                node.max[i] = max(node.left.max[i], node.right.max[i])
        return node

    def update(self, pos, val):
        self._update(self.root, pos, val)

    def _update(self, node, pos, val):
        if node.l == node.r == pos:
            for i in range(self.k):
                node.min[i] = val[i]
                node.max[i] = val[i]
        else:
            mid = (node.l + node.r) // 2
            if pos <= mid:
                self._update(node.left, pos, val)
            else:
                self._update(node.right, pos, val)
            # Merge results
            for i in range(self.k):
                node.min[i] = min(node.left.min[i], node.right.min[i])
                node.max[i] = max(node.left.max[i], node.right.max[i])

    def query_range(self, l, r):
        return self._query_range(self.root, l, r)

    def _query_range(self, node, l, r):
        if node.r < l or node.l > r:
            return None, None  # min, max for each dimension
        if l <= node.l and node.r <= r:
            return node.min, node.max

        left_min, left_max = self._query_range(node.left, l, r)
        right_min, right_max = self._query_range(node.right, l, r)

        # Merge results
        if left_min is None:
            merged_min = right_min
        elif right_min is None:
            merged_min = left_min
        else:
            merged_min = [min(left_min[i], right_min[i]) for i in range(self.k)]

        if left_max is None:
            merged_max = right_max
        elif right_max is None:
            merged_max = left_max
        else:
            merged_max = [max(left_max[i], right_max[i]) for i in range(self.k)]

        return merged_min, merged_max

def main():
    import sys
    input = sys.stdin.read()
    data = input.split()

    idx = 0
    n = int(data[idx])
    idx += 1
    k = int(data[idx])
    idx += 1

    points = []
    for _ in range(n):
        coords = list(map(int, data[idx:idx+k]))
        idx += k
        points.append(coords)

    st = SegmentTree(points, k)

    q = int(data[idx])
    idx += 1

    output = []
    for _ in range(q):
        t = int(data[idx])
        idx += 1

