        target = a[0]
        ops = []

        # First pass: reduce elements greater than target
        for i in range(n):
            if a[i] > target:
                # Transfer to position 1
                x = (a[i] - target) // i
                ops.append((i+1, 1, x))
                a[i] -= x * i

        # Second pass: increase elements less than target
        for i in range(n):
            if a[i] < target:
                # Receive from position 1
                x = (target - a[i]) // i
                ops.append((1, i+1, x))
                a[i] += x * i

        # Check if all are equal
        if all(x == target for x in a):
            print(len(ops))
            for op in ops:
                print(*op)
        else:
            print(-1)

