def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

t = int(input())
for _ in range(t):
    n, k = map(int, input().split())
    s = input().strip()

    # Count frequency of each bead color
    freq = {}
    for c in s:
        if c in freq:
            freq[c] += 1
        else:
            freq[c] = 1

    max_length = 0

    # Try all possible lengths of necklace from 1 to n
    for m in range(1, n + 1):
        d = gcd(m, k)  # Number of groups

        # Calculate maximum beads we can assemble
        total_beads = 0
        for f in freq.values():
            # Maximum full groups we can assign this color
group_count = f // d
            total_beads += group_count * d

        # If we can assemble at least m beads, this length is possible
        if total_beads >= m:
            max_length = m

    print(max_length)
