    if from_c == 1 and to_c == 2:
        return 2
    elif from_c == 1 and to_c == 3:
        return 1
    elif from_c == 2 and to_c == 1:
        return 2
    elif from_c == 2 and to_c == 3:
        return 1
    elif from_c == 3 and to_c == 1:
        return 1
    elif from_c == 3 and to_c == 2:
        return 2
    else:
        # same computer
        return 0

def solve():
    n = int(input())
    computers = list(map(int, input().split()))

    # Build adjacency list for dependencies
    dependencies = [[] for _ in range(n)]
    for i in range(n):
        parts = list(map(int, input().split()))
        ki = parts[0]
        if ki > 0:
            dependencies[i] = parts[1:]

    # Topologically sort parts
    in_degree = [0] * n
    for i in range(n):
        for dep in dependencies[i]:
            in_degree[dep - 1] += 1  # assuming parts are 1-indexed

    # Use Kahn's algorithm for topological sort
    top_order = []
    for i in range(n):
        if in_degree[i] == 0:
            top_order.append(i)

    # Process parts in topological order
    dp = [0, 0, 0]  # dp[0] = computer 1, dp[1] = computer 2, dp[2] = computer 3

    for i in top_order:
        required_c = computers[i] - 1  # convert to 0-indexed

        # Create new DP values for this state
        new_dp = [float('inf')] * 3

        for prev_c in range(3):
            # Cost to move from prev_c to required_c + 1 hour to complete
            move_cost = move_cost(prev_c, required_c)
            total_time = dp[prev_c] + move_cost + 1

            # Update new_dp[required_c]
            if total_time < new_dp[required_c]:
                new_dp[required_c] = total_time

        # Update dp with the new state
        for c in range(3):
            if new_dp[c] < dp[c]:
                dp[c] = new_dp[c]

    print(min(dp))

solve()
