def solve():
    MOD = 10**9 + 7

    n, m = map(int, input().split())

    # Count how many gyms have each multiset of counts
    count_map = {}
    for _ in range(n):
        g_i = list(map(int, input().split()))
        g = g_i[0]
        types = g_i[1:]

        # Count occurrences of each type in this gym
        count = {}
        for t in types:
            count[t] = count.get(t, 0) + 1

        # Get a sorted tuple of counts (canonical signature)
        sorted_counts = tuple(sorted(count.values()))

        count_map[sorted_counts] = count_map.get(sorted_counts, 0) + 1

    # The answer is the product of factorials of the sizes of each group
    result = 1
    for k in count_map.values():
        result = (result * factorial(k, MOD)) % MOD

    print(result)

# Compute factorial modulo MOD
def factorial(k, MOD):
    result = 1
    for i in range(2, k + 1):
        result = (result * i) % MOD
    return result

