            val_to_neighbors[val] = []
            for neighbor in adj[pos]:
                if a[neighbor] in val_to_remaining:
                    val_to_neighbors[val].append(a[neighbor])

        # Build adjacency list for elements in b and remaining elements
        adj_b = [[] for _ in range(len(b) + 1)]  # 1-indexed
        for i, val in enumerate(b):
            for neighbor in val_to_neighbors[val]:
                adj_b[i+1].append(neighbor)

