n, m = map(int, input().split())

type_to_gym_count = {}  # dictionary for each type
# We'll store {type: {gym: count, ...}, ...}

type_to_gym_set = {}  # dictionary for each type
# We'll store {type: set of gyms, ...}

# Process each gym
for gym_idx in range(1, n + 1):
    parts = list(map(int, input().split()))
    g = parts[0]
    types = parts[1:]

    # Count occurrences of each type in this gym
    # We'll use a temporary dictionary for the current gym
    gym_count = {}

    for t in types:
        gym_count[t] = gym_count.get(t, 0) + 1

    # Update type counts and gym sets
    for t, count in gym_count.items():
        if t not in type_to_gym_count:
            type_to_gym_count[t] = {}
            type_to_gym_set[t] = set()

        type_to_gym_count[t][gym_idx] = count
        type_to_gym_set[t].add(gym_idx)

# Build multisets and count groups
from collections import defaultdict

group = defaultdict(int)

type_multisets = {}
for t in type_to_gym_count:
    # Get the multiset of (gym, count) pairs for this type
    multis = []
    for gym_idx in type_to_gym_set[t]:
        count_t = type_to_gym_count[t][gym_idx]
        multis.append((gym_idx, count_t))
    multis.sort()
    type_multisets[t] = tuple(multis)
    group[tuple(multis)] += 1

# The number of valid permutations is the product of factorials of group sizes

def factorial(x):
    if x == 0:
        return 1
    res = 1
    for i in range(1, x + 1):
        res = res * i % MOD
    return res

result = 1
for v in group.values():
    result = result * factorial(v) % MOD

print(result)
