def find_cycles(n, crush):
    visited = [False] * (n + 1)
    cycles = []

    for i in range(1, n + 1):
        if not visited[i]:
            stack = []
            v = i
            while True:
                if visited[v]:
                    if v in stack:
                        idx = stack.index(v)
                        cycle = stack[idx:]
                        cycles.append(len(cycle))
                    break
                visited[v] = True
                stack.append(v)
                v = crush[v]
    return cycles

