def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Find next smaller element to the right using a monotonic stack
    stack = []  # stack of indices
    next_smaller = [-1] * n

    for i in range(n - 1, -1, -1):
        # Pop elements from stack that are >= current age
        while stack and a[stack[-1]] >= a[i]:
            stack.pop()

        if stack:
            next_smaller[i] = stack[-1]
        else:
            next_smaller[i] = -1

        stack.append(i)

    # Calculate displeasure for each walrus
    result = []
    for i in range(n):
        if next_smaller[i] == -1:
            result.append("-1")
        else:
            displeasure = next_smaller[i] - i - 1
            result.append(str(displeasure))

    print(" ".join(result))

solve()
