def solve():
    n, x = map(int, input().split())
    a = list(map(int, input().split()))

    # If no modes, we can only determine k if x == 2
    if n == 0:
        if x == 2:
            print(0)
        else:
            print(-1)
        return

    # Try each number of modes from 1 to n
    for modes_needed in range(1, n + 1):
        # Try all combinations of that many modes
        from itertools import combinations
        for indices in combinations(range(n), modes_needed):
            # Get the modes
            selected_modes = [a[i] for i in indices]

            # Check if this subset uniquely determines k
            unique_k = None
            for k in range(2, x + 1):
                results = []
                for ai in selected_modes:
                    b = (k + ai - 1) // ai  # ceil division
                    results.append(b)

                # Check if this result set is unique
                duplicate = False
                for k2 in range(2, x + 1):
                    if k2 == k:
                        continue
                    results2 = []
                    for ai in selected_modes:
                        b2 = (k2 + ai - 1) // ai
                        results2.append(b2)
                    if results == results2:
                        duplicate = True
                        break

                if not duplicate:
                    if unique_k is None:
                        unique_k = k
                    else:
                        # Multiple k values with unique results
                        break

            # If we found a unique k and no duplicates
            if unique_k is not None and not duplicate:
                print(modes_needed)
                return

    # No solution found
    print(-1)

solve()
