import sys

def solve():
    t = sys.stdin.readline().strip()
    ice_pieces = sys.stdin.readline().strip()

    # Count occurrences in t
    count_t = {}
    for c in t:
        count_t[c] = count_t.get(c, 0) + 1

    # Count occurrences in ice pieces
    count_ice = {}
    for c in ice_pieces:
        count_ice[c] = count_ice.get(c, 0) + 1

    # Function to get available pieces for a given digit d
    def available_pieces(d):
        if d == '2' or d == '5':
            # Can use either '2' or '5'
            return count_ice.get('2', 0) + count_ice.get('5', 0)
        elif d == '6' or d == '9':
            # Can use either '6' or '9'
            return count_ice.get('6', 0) + count_ice.get('9', 0)
        else:
            # Can only use exact digit
            return count_ice.get(d, 0)

    # Calculate maximum instances
    max_instances = float('inf')
    for digit, needed in count_t.items():
        available = available_pieces(digit)
        if available < needed:
            # We need at least 'needed' pieces for this digit
            # But we only have 'available', so the limit is available // needed
            max_instances = min(max_instances, available // needed)
        else:
            # We have enough, so no limit from this digit
            pass

    print(max_instances if max_instances != float('inf') else 0)

if __name__ == "__main__":
    solve()
