def find_min_k(s):

    # For each character, find the maximum gap between consecutive occurrences
    # The minimum k for a character to be dominant is this max gap

    min_k = float('inf')

    # Process each character separately
    for c in set(s):
        gaps = []
        prev = -1

        for i, ch in enumerate(s):
            if ch == c:
                if prev != -1:
                    gaps.append(i - prev - 1)
                prev = i

        # Add gap from start to first occurrence
        if prev != -1:
            gaps.append(prev)
        # Add gap from last occurrence to end
        if prev != -1:
            gaps.append(len(s) - prev - 1)

        # The character is k-dominant if all gaps ≤ k
        # So minimum k for this character is the max gap
        if gaps:
            max_gap = max(gaps)
            min_k = min(min_k, max_gap)

    return min_k

s = input().strip()
print(find_min_k(s))
"}

