def is_k_dominant(s, k, char):
    # Check if char appears in every substring of length at least k
    n = len(s)
    for i in range(n - k + 1):
        # Check substring from i to i+k-1
        found = False
        for j in range(i, i + k):
            if s[j] == char:
                found = True
                break
        if not found:
