def factorize(n):
    factors = []
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

def k_factorization(n, k):
    factors = factorize(n)

    if len(factors) < k:
        return -1

    result = []
    # Use the smallest prime factor (which is 2) for the first k-1 numbers
    for _ in range(k - 1):
        result.append(2)

    # The last number gets the remaining product
    last = n
    for _ in range(k - 1):
        last //= 2

    result.append(last)
    return result

