def product_of_digits(n):
    prod = 1
    while n > 0:
        prod *= n % 10
        n //= 10
    return prod

def max_product(n):
    s = str(n)
    digits = list(map(int, s))

    # Check the original number
    original = int(''.join(map(str, digits)))
    max_prod = product_of_digits(original)

    # Try all numbers with the same number of digits
    for i in range(len(digits)):
        if digits[i] == 0:
            continue

        # Try decreasing this digit by 1
        new_digits = digits[:]
        new_digits[i] -= 1

        if new_digits[i] >= 0:
            # Set all subsequent digits to 9
            for j in range(i+1, len(new_digits)):
                new_digits[j] = 9

            new_num = int(''.join(map(str, new_digits)))
            if new_num <= n:
                p = product_of_digits(new_num)
                if p > max_prod:
                    max_prod = p

    return max_prod

n = int(input())
print(max_product(n))
