def is_subsequence(s, t):
    """Check if t is a subsequence of s"""
    if len(t) > len(s):
        return False

    i = 0  # index for s
    j = 0  # index for t

    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            j += 1
        i += 1

    return j == len(t)

def can_match(s, t, i, j):
    """Check if s[i] can match t[j], considering characters before and after"""
    # Check if we can match t[0..j-1] before position i
    before = 0
    k = 0  # index for t[0..j-1]
    for l in range(i):
        if k < len(t[:j]) and s[l] == t[k]:
            k += 1

    if k < len(t[:j]):
        return False

    # Check if we can match t[j+1..|t|-1] after position i
    after = 0
    k = 0  # index for t[j+1..|t|-1]
    for l in range(i + 1, len(s)):
        if k < len(t[j+1:]) and s[l] == t[j+1 + k]:
            k += 1

    return k == len(t[j+1:])

def solve():
    s = input().strip()
    t = input().strip()

    if not is_subsequence(s, t):
        print("No")
        return

    for i in range(len(s)):
        found = False
        for j in range(len(t)):
            if s[i] == t[j]:
                if can_match(s, t, i, j):
                    found = True
                    break
        if not found:
            print("No")
            return

    print("Yes")

solve()
