    divisors = 1
    i = 2
    while i * i <= b:
        if b % i == 0:
            # Count exponents of i
            exp = 0
            while b % i == 0:
                b //= i
                exp += 1
            divisors *= (exp + 1)
        i += 1
    if b > 1:
        divisors *= 2
    return divisors

