import math

def count_divisors(n):
    """Count the number of divisors of n"""
    count = 0

    # Count divisors from 1 to sqrt(n)
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                # i is the square root
                count += 1
            else:
                # i and n/i are distinct divisors
                count += 2

    return count

def solve():
    b = int(input())
    print(count_divisors(b))

if __name__ == "__main__":
    solve()
"}

