import sys

def count_divisors(n):
    if n == 0:
        return 0
    count = 1
    i = 2
    while i * i <= n:
        exponent = 0
        while n % i == 0:
            exponent += 1
            n //= i
        count *= (exponent + 1)
        i += 1
    if n > 1:
        count *= 2
    return count

# Read input
