def solve():
    n, k = map(int, input().split())

    # If k == 1, all characters must be 'a'
    if k == 1:
        print('a' * n)
        return

    # If n == 1, no adjacent pairs
    if n <= 1:
        print('a')
        return

    # For k >= 2, use a pattern to minimize repeated adjacent pairs
    # Pattern: a b a c a d a e a f a ...
    # Use 'a' for most positions, introduce new characters to break patterns

    result = []
    result.append('a')  # Start with 'a'

    # Alternate between 'a' and a new character
    for i in range(1, n):
        if i % 2 == 1:
            # After 'a', use 'b', then 'a', then 'c', etc.
            if i // 2 >= len(result) - 1:
                result.append(chr(ord('a') + len(result)))
            else:
                result.append('a')
        else:
            result.append('a')

    print(''.join(result))

solve()
