def solve():
    n, k = map(int, input().split())

    # If k == 1, all characters must be 'a'
    if k == 1:
        print('a' * n)
        return

    # If n == 1, no adjacent pairs
    if n <= 1:
        print('a')
        return

    # Pattern: start with 'a' (twice), then use alternating pattern
    result = []
    result.append('a')
    result.append('a')

    # For the remaining positions
    for i in range(2, n):
        offset = i - 2
        if offset % 2 == 0:
            # Use the next character (b, c, d, e, f, ...) for even offsets
            result.append(chr(ord('a') + 1 + (offset // 2)))
        else:
            # Use alternating 'a' and 'b' for odd offsets
            if (offset // 2) % 2 == 0:
                result.append('a')
            else:
                result.append('b')

    print(''.join(result))

solve()
"}

