import sys


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    b = [int(next(it)) for _ in range(n)]
    m = int(next(it))

    # Sort both sequences by x-coordinate
    a.sort()
    b.sort()

    # DP[i][j] = number of ways to interleave first i elements of a
    # and first j elements of b while maintaining non-decreasing property

    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(n):
            # If we add a[i] next, it must be >= the last element in the current result
            # The last element in the current result is either a[i-1] or b[j-1]
            if i > 0:
                if a[i] >= a[i-1]:
                    dp[i+1][j] += dp[i][j]
            if j > 0:
                if a[i] >= b[j-1]:
                    dp[i+1][j] += dp[i][j]

            # If we add b[j] next, it must be >= the last element in the current result
            if i > 0:
                if b[j] >= a[i-1]:
                    dp[i][j+1] += dp[i][j]
            if j > 0:
                if b[j] >= b[j-1]:
                    dp[i][j+1] += dp[i][j]

            # Apply modulo
            dp[i+1][j] %= m
            dp[i][j+1] %= m

    print(dp[n][n] % m)

if __name__ == "__main__":
    solve()
"}

