def solve():
    k, d = map(int, input().split())

    if k == 1:
        if d == 0:
            print("0")
        else:
            print(d)
    elif d == 0:
        print("No solution")
    else:
        # Need a k-digit number with sum of digits = d (since d ≤ 9 and k ≥ 2, 1 + (d-1) ≤ 9)
        # Construct: 1 followed by (k-2) zeros, then add (d-1) to the last digit

        # Start with k zeros, set first digit to 1
        num = [0] * k
        num[0] = 1

        # We need sum = d, have sum = 1 already
        needed = d - 1

        # Add to last digit first
        if needed <= 9:
            num[-1] = needed
        else:
            # Add 9 to last digit
            num[-1] = 9
            needed -= 9

            # Now add to previous digits
            for i in range(k - 2, -1, -1):
                if needed <= 9:
                    num[i] += needed
                    break
                num[i] = 9
                needed -= 9

        print(''.join(map(str, num)))

solve()
