import sys
import math

def solve():
    n = int(sys.stdin.readline())
    if n == 1:
        print("0.000000")
        return

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    # We'll use an iterative post-order traversal to calculate expected values
    expected = [0.0] * (n + 1)

    # To perform iterative DFS, we'll use a stack and a visited set
    stack = [(1, -1, False)]  # (node, parent, visited)

    # Process nodes in post-order
    while stack:
        u, parent, visited = stack.pop()
        if not visited:
            stack.append((u, parent, True))
            # Push children to stack (except parent)
            for v in adj[u]:
                if v != parent:
                    stack.append((v, u, False))
        else:
            # Calculate expected value for this node
            children = []
            for v in adj[u]:
                if v != parent:
                    children.append(v)

            # If no children, it's a leaf
            if not children:
                expected[u] = 0.0
            else:
                total = 0.0
                for v in children:
                    total += expected[v]
                expected[u] = 1.0 + (total / len(children))

    result = expected[1]

    # Format with enough precision
    # We need to print with at least 6 decimal places

    # Check if result is an integer
    if abs(result - round(result)) < 1e-10:
        print(f"{int(result):d}.000000")
    else:
        print(f"{result:.15f}")

if __name__ == "__main__":
    solve()
"}

