def can_complete_wall(heights):
    n = len(heights)

    # Keep placing bricks until no adjacent equal pairs remain
    while True:
        # Find the first adjacent pair with equal heights
        found = False
        for i in range(n - 1):
            if heights[i] == heights[i + 1]:
                # Place a brick, increasing both by 1
                heights[i] += 1
                heights[i + 1] += 1
                found = True
                break

        # If we didn't find any pair, check if all heights are equal
        if not found:
            return all(h == heights[0] for h in heights)

n = int(input())
a = list(map(int, input().split()))

if can_complete_wall(a):
    print("YES")
else:
    print("NO")
