def count_crosses(n, m, s):
    count = 0

    # Iterate through all possible centers (x0, y0)
    for x0 in range(1, n + 1):
        for y0 in range(1, m + 1):
            # Maximum possible size for vertical/horizontal rectangles at this center
            max_a = min(x0 - 1, n - x0)
            max_b = min(y0 - 1, m - y0)

            # Store all possible vertical rectangles and their areas
            vertical_areas = {}
            for a in range(0, max_a + 1):
                for b in range(0, max_b + 1):
                    vertical_area = (2 * a + 1) * (2 * b + 1)
                    vertical_areas[(a, b)] = vertical_area

            # For each vertical rectangle, find matching horizontal rectangles
            for (a, b), vertical_area in vertical_areas.items():
                target = s - vertical_area
                if target < 0:
                    continue

                # Find all horizontal rectangles that complement this vertical rectangle
                for c in range(0, max_a + 1):
                    for d in range(0, max_b + 1):
                        horizontal_area = (2 * c + 1) * (2 * d + 1)
                        overlap_area = (2 * min(a, c) + 1) * (2 * min(b, d) + 1)
                        total_area = horizontal_area - overlap_area

                        if total_area == target:
                            count += 1

    return count

n, m, s = map(int, input().split())
