                for c in range(0, max_a + 1):
                    for d in range(0, max_b + 1):
                        horizontal_area = (2 * c + 1) * (2 * d + 1)
                        overlap_area = (2 * min(a, c) + 1) * (2 * min(b, d) + 1)
                        total_area = horizontal_area - overlap_area

                        if total_area == target:
                            count += 1

    return count

