import sys

def is_possible(fillings, d, n):
    # Greedy approach: try to place patty-cakes with minimum distance d
    #
    # Place the first patty-cake of each type at positions 0, 1, 2, ...
    # Then, for each subsequent patty-cake of the same type, we need to place it at least d+1 away
    #
    # We'll keep track of the last position of each filling
    freq = {}
    for filling in fillings:
        if filling not in freq:
            freq[filling] = 1
        else:
            freq[filling] += 1

    last_pos = {f: -d-1 for f in freq}

    # Try to place all patty-cakes
    for filling in fillings:
        if last_pos[filling] == -d-1:
            # First occurrence, place at 0
            pos = 0
        else:
            # Subsequent occurrence, need at least d+1 away
            pos = last_pos[filling] + d + 1

        last_pos[filling] = pos

        # If we go out of bounds, it's not possible
        if pos > n - 1:
            return False

    return True

