def find_cycle_lengths(n, crush):
    visited = [False] * n
    cycle_lengths = []

    for i in range(n):
        if not visited[i]:
            # Find the cycle
            current = i
            path = []

            while True:
                if visited[current]:
                    if path and path[-1] == current:
                        # self-loop at current
                        cycle_lengths.append(1)
                    else:
                        # Found a cycle: current is in the path
                        cycle_start_idx = path.index(current)
                        cycle = path[cycle_start_idx:]
                        cycle_lengths.append(len(cycle))
                    break

                path.append(current)
                visited[current] = True
                current = crush[current]

    return cycle_lengths

