n, m, k = map(int, input().split())

# Union-Find (Disjoint Set Union)
class DSU:
    def __init__(self, n):
        self.parent = list(range(n + 1))  # 1-indexed
        self.rank = [1] * (n + 1)
        self.size = n  # total people

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)

        if x_root == y_root:
            return

        if self.rank[x_root] < self.rank[y_root]:
            x_root, y_root = y_root, x_root

        self.parent[y_root] = x_root
        self.rank[x_root] += self.rank[y_root]

    def get_size(self, x):
        return self.rank[self.find(x)]

# Initialize
dsu = DSU(n)

# We need to read all edges first
edges = []
for _ in range(m):
    x, y = map(int, input().split())
    edges.append((x, y))

# Process edges and output results
for day, (x, y) in enumerate(edges, start=1):
    dsu.union(x, y)
    component_size = dsu.get_size(x)

    # If the component size is s, we can select min(s, s - 1)
    # This works because in a complete graph of size s, each node has degree s-1
    if component_size >= k:
        max_selected = min(component_size, component_size - 1)
        print(max_selected)
    else:
        print(0)
