for r in row_elements:
    all_columns.update(row_elements[r])

# Find rows that have all elements
covered_rows = set()
for r in all_rows:
    # Add this row to covered rows
    covered_rows.add(r)

    # Add all other rows that share at least one column
    for other_r in row_elements:
        if other_r != r and other_r not in covered_rows:
            # Check if there's any column overlap
            if row_elements[r].intersection(row_elements[other_r]):
                covered_rows.add(other_r)

# Count rows not covered
rows = set(range(1, n + 1))
uncovered_rows = rows - covered_rows

print(len(uncovered_rows))
