import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(n):
        grid.append(list(map(int, sys.stdin.readline().split())))

    result = [[0] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            # Collect all heights from the i-th East street
            east_heights = [(grid[i][k], k) for k in range(m)]
            # Collect all heights from the j-th South street
            south_heights = [(grid[k][j], k) for k in range(n)]

            # Combine and sort by height
            all_heights = east_heights + south_heights
            all_heights.sort(key=lambda x: x[0])

            # Assign ranks
            rank = 1
            prev_height = None
            for height, pos in all_heights:
                if height != prev_height:
                    rank += 1
                prev_height = height
            result[i][j] = rank

    for row in result:
        print(' '.join(map(str, row)) + ' ')

if __name__ == "__main__":
    solve()
