import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(n):
        grid.append(list(map(int, sys.stdin.readline().split())))

    result = [[0] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            # Collect all skyscrapers on the i-th East street
            east_skyscrapers = [(grid[i][k], k) for k in range(m)]
            # Collect all skyscrapers on the j-th South street
            south_skyscrapers = [(grid[k][j], k) for k in range(n)]

            # Combine skyscrapers from both streets
            skyscrapers = east_skyscrapers + south_skyscrapers

