import sys

def restore_ipv6(short):
    blocks = short.split(':')

    if '::' in blocks:
        non_zero_count = 0
        for block in blocks:
            if block != '':
                non_zero_count += 1

        zero_blocks = 8 - non_zero_count

        col_index = blocks.index('::')
        prefix = blocks[:col_index]
        suffix = blocks[col_index + 1:]

        full = ''
        full += ':'.join(prefix) + ':'
        full += '0000:' * zero_blocks
        full += ':'.join(suffix)
        return full
    else:
        full = ''
        for block in blocks:
            if block == '':
                full += '0000:
            else:
                full += block.zfill(4) + ':'
        return full[:-1]

n = int(sys.stdin.readline())
for _ in range(n):
    short = sys.stdin.readline().strip()
    print(restore_ipv6(short))
