# We'll use 1-based indexing

disjoint_set = {}

# Find root of a node using path compression
def find(node):
    if node not in disjoint_set or disjoint_set[node] == node:
        disjoint_set[node] = node
        return node
    return find(disjoint_set[node])

# Union two nodes
def union(a, b):
    root_a = find(a)
    root_b = find(b)
    if root_a != root_b:
        disjoint_set[root_a] = root_b

# Process queries
for _ in range(q):
    r, c = map(int, input().split())
    # Connect row r to column c
    if r not in disjoint_set:
        disjoint_set[r] = r
    if c not in disjoint_set:
        disjoint_set[c] = c
    union(r, c)

# Now find max connected component size
max_size = 0
for node in disjoint_set:
    root = find(node)
    # Count nodes in this connected component
    component_size = 0
    for key in disjoint_set:
        if find(key) == root:
            component_size += 1
    max_size = max(max_size, component_size)

# Calculate answer
answer = n + m - 2 * max_size
print(answer)
