def solve():
    n = int(input())
    c = list(map(int, input().split()))

    # Build adjacency list for dependencies
    graph = [[] for _ in range(n + 1)]  # 1-indexed
    for i in range(1, n + 1):
        parts = list(map(int, input().split()))
        k = parts[0]
        dependencies = parts[1:]
        graph[i] = dependencies

    # DP: dp[mask][cur][last] = minimum time
    # mask: bitmask of completed parts
    # cur: current computer (1, 2, 3)
    # last: last completed part (1-indexed)
    INF = float('inf')
    dp = [[[INF] * (n + 1) for _ in range(4)] for _ in range(1 << n)]

    # Initial states: start at any computer with no parts completed
    for computer in range(1, 4):
        dp[0][computer][0] = 0

    for mask in range(1 << n):
        for computer in range(1, 4):
            for last in range(n + 1):
                if dp[mask][computer][last] == INF:
                    continue

                # Try completing any part that hasn't been completed
                # and whose dependencies are all satisfied
                for part in range(1, n + 1):
                    if (mask & (1 << (part - 1))) == 0 and all(mask & (1 << (dep - 1)) for dep in graph[part]):
                        # Calculate time to complete this part
                        # Time = time to move from current computer to the part's computer
                        # plus 1 hour for completing the part
                        move_time = 0
                        if computer == 1:
                            if c[part - 1] == 2:
                                move_time = 1
                            else:  # c[part - 1] == 3
                                move_time = 2
                        elif computer == 2:
                            if c[part - 1] == 1:
                                move_time = 2
                            else:  # c[part - 1] == 3
                                move_time = 1
                        elif computer == 3:
                            if c[part - 1] == 1:
                                move_time = 1
                            else:  # c[part - 1] == 2
