def count_crosses(n, m, s):

    # Try all possible centers (x0, y0)
    for x0 in range(1, n + 1):
        for y0 in range(1, m + 1):

            # Try all possible (a, b)
            for a in range(n + 1):
                for b in range(m + 1):

                    # Try all possible (c, d)
                    for c in range(n + 1):
                        for d in range(m + 1):

                            # Create set for vertical bar
                            vertical = set()
                            for x in range(max(1, x0 - a), min(n, x0 + a) + 1):
                                for y in range(max(1, y0 - b), min(m, y0 + b) + 1):
                                    vertical.add((x, y))

                            # Create set for horizontal bar
                            horizontal = set()
                            for x in range(max(1, x0 - c), min(n, x0 + c) + 1):
                                for y in range(max(1, y0 - d), min(m, y0 + d) + 1):
                                    horizontal.add((x, y))

                            # Create set for cross
                            cross = vertical.union(horizontal)

                            # Calculate area
                            area = len(cross)

                            if area == s:
                                yield 1

    # Count total
    total = 0
    for cnt in count_crosses(n, m, s):
        total += cnt

    return total

# Read input
n, m, s = map(int, input().split())

# Compute result
result = count_crosses(n, m, s)

# Output result
print(result)
