    if not data:
        return

    h = int(data[0])
    a = list(map(int, data[1:1+h+1]))

    # Check if there's only one valid configuration
    has_multiple = False
    for i in range(h):
        if i == h - 1:
            break  # last level has no children

        # At level i, we have a[i] vertices
        # They need to have children summing to a[i+1]

        if a[i+1] == 0:
            continue  # no children to assign, only one way

        if a[i] == 1:
            continue  # only one vertex at level i, must assign all children to it

        # Multiple vertices at level i, a[i+1] > 0
        has_multiple = True
        break

    if not has_multiple:
        print("perfect")
        return

    # Build two different trees
    print("ambiguous")

    # Tree 1: assign all children to first vertex at each level
    # Tree 2: assign all children to last vertex at each level

    # Find the order of vertices
    order = []
    level = {0: [0]}
    next_id = 1

    for i in range(h + 1):
        vertices = []
        if i == 0:
            vertices = [0]  # root
        else:
            # Collect vertices at level i
            vertices = level[i - 1]

            # For each vertex, we need to assign children
            children_count = a[i]

            # Distribute children to vertices
            for v in vertices:
                if children_count == 0:
                    break
                if i == h:
                    continue  # no children for leaves

                # Determine how many children to assign
                if len(vertices) > 1:
                    if i == h - 1:
                        # Last level has no children
                        continue

                    # Assign all children to one vertex
                    if i == 0:
                        # Root has a[1] children
                        first_vertex = 0
                        last_vertex = len(vertices) - 1
                    else:
                        first_vertex = vertices[0]
                        last_vertex = vertices[-1]

                    if i == h - 1:
                        # Last level has no children
                        children_count = 0
                    else:
                        children_count = a[i + 1]

                    if children_count == 0:
                        continue

                    # Assign children_count to first vertex
                    if i == 0:
                        # Root's children
                        for j in range(children_count):
                            order.append(first_vertex + j)
                            next_id += 1
                    else:
                        # Children of vertices[0]
                        for j in range(children_count):
                            order.append(next_id + j)
                            next_id += 1
                else:
                    # Only one vertex at this level
                    continue

        level[i] = vertices

    # Build parent arrays
    tree1 = [0] * next_id
    tree2 = [0] * next_id

    for i in range(h + 1):
        vertices = level[i]

        if i == 0:
            parent = vertices  # root
        else:
            parent = vertices

        for v in vertices:
            if i == h:
                continue

            # Find number of children for this vertex
            children_count = a[i]

            # In tree1, assign all children to first vertex
            # In tree2, assign all children to last vertex
            if len(vertices) > 1:
                first_idx = 0
                last_idx = len(vertices) - 1

                # Children are already added to order
                # Find which children belong to this vertex
                first_child = order[vertices.index(v) * children_count + first_idx]
                last_child = order[vertices.index(v) * children_count + last_idx]

                # In tree1, assign all children to first child
                if i == 0:
                    first_vertex = vertices[0]
                    last_vertex = vertices[-1]
                else:
                    first_vertex = vertices[0]
                    last_vertex = vertices[-1]

                for child in range(first_child, next_id):
