def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # dp[h] = maximum number of potions we can drink with health h
    dp = {0: 0}

    for i in range(n):
        new_dp = {}
        ai = a[i]

        # Try not drinking the potion
        for h, count in dp.items():
            if h not in new_dp or count > new_dp[h]:
                new_dp[h] = count

        # Try drinking the potion
        for h, count in dp.items():
            new_h = h + ai
            if new_h >= 0:
                new_count = count + 1
                if new_h not in new_dp or new_count > new_dp[new_h]:
                    new_dp[new_h] = new_count

        dp = new_dp

    print(max(dp.values()))

solve()
"}

