def is_subsequence(a, b):
    """Check if a is a subsequence of b"""
    it = iter(b)
    return all(c in it for c in a)


def main():
    s = input().strip()
    t = input().strip()

    # Check if t is a subsequence of s
    if not is_subsequence(t, s):
        print("No")
        return

    # Check if t is exactly the same length as s
    if len(t) == len(s):
        print("Yes")
        return

    # For each character in s, check if it can be part of some subsequence matching t
    for i, char in enumerate(s):
        # Check if this character can be part of some subsequence matching t
        # We need to find a k such that:
        # - t[0..k-1] is a subsequence of s[0..i-1]
        # - t[k..n-1] is a subsequence of s[i+1..n-1]

        # Try all possible splits
        for k in range(len(t)):
            if k > 0 and t[:k] != t[:k]:
                continue
            if k < len(t) and t[k:] != t[k:]:
                continue

            # Check prefix before i
            prefix = t[:k]
            if not is_subsequence(prefix, s[:i]):
                continue

            # Check suffix after i
            suffix = t[k:]
            if not is_subsequence(suffix, s[i+1:]):
                continue

            # This character can be part of some subsequence
            break
        else:
            # No split found that works
            print("No")
            return

    print("Yes")

if __name__ == "__main__":
    main()
