# Determine the pattern by looking at the first occurrence of each color
pattern = [None] * 4

# Find where each color appears
for i, ch in enumerate(s):
    if ch == 'R' and pattern[0] is None:
        pattern[0] = i % 4
    elif ch == 'B' and pattern[1] is None:
        pattern[1] = i % 4
    elif ch == 'Y' and pattern[2] is None:
        pattern[2] = i % 4
    elif ch == 'G' and pattern[3] is None:
        pattern[3] = i % 4

# Construct the expected pattern based on which position each color should be in
expected = [''] * 4
for i in range(4):
    if i % 4 == pattern[0]:
        expected[i] = 'R'
    if i % 4 == pattern[1]:
        expected[i] = 'B'
    if i % 4 == pattern[2]:
        expected[i] = 'Y'
    if i % 4 == pattern[3]:
        expected[i] = 'G'

# Count dead bulbs
kr = kb = ky = kg = 0
for i, ch in enumerate(s):
    if ch == '!':
        # The position should have a specific color
        pos = i % 4
        if expected[pos] == 'R':
            kr += 1
        elif expected[pos] == 'B':
            kb += 1
        elif expected[pos] == 'Y':
            ky += 1
        elif expected[pos] == 'G':
            kg += 1

print(kr, kb, ky, kg)
