def is_perfect_cube(n):
    """Check if n is a perfect cube"""
    if n == 0:
        return True

    # Estimate cube root using binary search
    low, high = 1, n
    while low <= high:
        mid = (low + high) // 2
        cube = mid * mid * mid

        if cube == n:
            return True
        elif cube < n:
            low = mid + 1
        else:
            high = mid - 1

    return False

