        max_length = 0

        # Try all possible lengths from 1 to n
        for L in range(1, n + 1):
            m = gcd(L, k)  # Number of groups
            group_size = L // m

            # We need m groups, each with beads of the same color
            # And each group has group_size beads
            # We need to select m different colors with at least group_size beads each

            # Count how many colors have at least group_size beads
            count = 0
            for c in freq:
                if freq[c] >= group_size:
