import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    ages = list(map(int, data[1:1+n]))

    # next_smaller[i] = position of furthest walrus ahead with smaller age, or -1 if none
    next_smaller = [-1] * n

    # Use a stack to find next smaller elements
    stack = []  # stores indices of elements in decreasing order

    for i in range(n - 1, -1, -1):
        # Pop elements from stack that are >= current age
        while stack and ages[stack[-1]] >= ages[i]:
            stack.pop()

        if stack:
            # The top of the stack is the furthest younger walrus ahead
            next_smaller[i] = stack[-1]
        else:
            # No younger walrus ahead
            next_smaller[i] = -1

        # Push current index to stack
        stack.append(i)

    # Calculate displeasure
    result = []
    for i in range(n):
        if next_smaller[i] == -1:
            result.append('-1')
        else:
            displeasure = next_smaller[i] - i - 1
            result.append(str(displeasure))

    print(' '.join(result))

if __name__ == '__main__':
    solve()
