def is_connected(n, graph):
    visited = [False] * (n + 1)

    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)

    dfs(1)
    return all(visited[1:n+1])

